// FILE: payee-nickname.component.ts
import { Component } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-payee-nickname',
  standalone: true,
  imports: [FormsModule],
  template: `
    <label for="nickname">Saved payee nickname</label>
    <input id="nickname" name="nickname"
           [(ngModel)]="nickname" maxlength="40" />
    <p>Preview: {{ nickname || 'No nickname yet' }}</p>
    <button type="button" [disabled]="!nickname.trim()"
            (click)="save()">Save nickname locally</button>
    @if (saved) { <p role="status">Nickname saved in component state.</p> }
  `
})
export class PayeeNicknameComponent {
  nickname = '';
  saved = false;

  save(): void {
    this.saved = this.nickname.trim().length > 0;
  }
}

