// FILE: shipment-list.component.ts
import { Component, signal } from '@angular/core';

type ShipmentStatus = 'pending' | 'in-transit' | 'delivered';
interface Shipment { id: string; label: string; status: ShipmentStatus; }

@Component({
  selector: 'app-shipment-list',
  standalone: true,
  template: `
    <h2>Shipments</h2>
    @if (loading()) {
      <p role="status">Loading shipments...</p>
    } @else {
      <ul>
        @for (shipment of shipments(); track shipment.id) {
          <li>
            {{ shipment.label }} —
            @switch (shipment.status) {
              @case ('pending') { Pending pickup }
              @case ('in-transit') { On the way }
              @case ('delivered') { Delivered }
            }
          </li>
        } @empty {
          <li>No shipments to show.</li>
        }
      </ul>
    }
  `
})
export class ShipmentListComponent {
  readonly loading = signal(false);
  readonly shipments = signal<Shipment[]>([
    { id: 's-101', label: 'Parcel 101', status: 'pending' },
    { id: 's-102', label: 'Parcel 102', status: 'in-transit' }
  ]);
}

