import { Component, Pipe, PipeTransform } from '@angular/core';

type ShipmentStatus = 'pending' | 'in_transit' | 'delivered';

@Pipe({ name: 'shipmentStatus', standalone: true, pure: true })
export class ShipmentStatusPipe implements PipeTransform {
  transform(status: ShipmentStatus | string | null): string {
    switch (status) {
      case 'pending': return 'Pending pickup';
      case 'in_transit': return 'On the way';
      case 'delivered': return 'Delivered';
      default: return 'Status unavailable';
    }
  }
}

@Component({
  selector: 'app-shipment-summary',
  standalone: true,
  imports: [ShipmentStatusPipe],
  template: `<p>Shipment: {{ status | shipmentStatus }}</p>`
})
export class ShipmentSummaryComponent {
  status: ShipmentStatus = 'in_transit';
}

