import { Component, Pipe, PipeTransform, computed, signal } from '@angular/core';
import { CurrencyPipe } from '@angular/common';

type Category = 'electronics' | 'home' | 'books';
interface Product {
  id: string;
  title: string;
  category: Category;
  amount: number;
  currency: 'USD';
  inStock: boolean;
}

@Pipe({ name: 'categoryLabel', standalone: true, pure: true })
export class CategoryLabelPipe implements PipeTransform {
  transform(value: Category): string {
    const labels: Record<Category, string> = {
      electronics: 'Electronics', home: 'Home & Living', books: 'Books'
    };
    return labels[value];
  }
}

@Component({
  selector: 'app-product-catalog',
  standalone: true,
  imports: [CurrencyPipe, CategoryLabelPipe],
  template: `
    <h2>Product catalog</h2>
    <label for="catalog-search">Search products</label>
    <input id="catalog-search" type="search" [value]="query()"
           (input)="updateQuery($event)" />
    @if (query().trim()) {
      <p>Results for: {{ query() }}</p>
    }
    <ul aria-label="Matching products">
      @for (product of filteredProducts(); track product.id) {
        <li>
          <strong>{{ product.title }}</strong>
          <span>{{ product.category | categoryLabel }}</span>
          <span>{{ product.amount | currency:product.currency }}</span>
          @if (!product.inStock) { <span>Out of stock</span> }
        </li>
      } @empty {
        <li>No matching products.</li>
      }
    </ul>
  `
})
export class ProductCatalogComponent {
  readonly query = signal('');
  readonly products: Product[] = [
    { id: 'p-1', title: 'Notebook', category: 'books', amount: 12, currency: 'USD', inStock: true },
    { id: 'p-2', title: 'Desk lamp', category: 'home', amount: 29, currency: 'USD', inStock: false },
    { id: 'p-3', title: 'USB hub', category: 'electronics', amount: 35, currency: 'USD', inStock: true }
  ];
  readonly filteredProducts = computed(() => {
    const term = this.query().trim().toLowerCase();
    return this.products.filter(p => p.title.toLowerCase().includes(term));
  });

  updateQuery(event: Event): void {
    const input = event.target as HTMLInputElement;
    this.query.set(input.value);
  }
}
